// node tests/waste-depot-interior.mjs
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
// Source layout: game code lives in src/, houses.json is generated by `npm run build`.
const read=p=>readFileSync(new URL('../'+(p==='houses.json'?'dist/public/houses.json':'src/'+p),import.meta.url),'utf8');
const source=read('world/waste-depot-interior.js');
const router=read('world/shop-interior.js');
const main=read('main.js'),panel=read('ui/waste-depot-panel.js');
assert(router.includes("if(site.id==='landfill')return buildWasteDepotInterior(site,makeLabel,life);"));
assert(main.includes("wasteDepotPanel(life,thing.key.split(':')[1])"));
assert(panel.includes("life.place('landfill')"));
assert(panel.includes("workingAt(v,'landfill')"));
const V=class{constructor(x=0,y=0,z=0){this.x=x;this.y=y;this.z=z}set(x,y,z){Object.assign(this,{x,y,z})}};
const kit=(site,makeLabel,title)=>{
 const group={add(){}},colliders=[],interactables=[],sceneObjects=[],placedProps=[];
 const box=()=>{};
 const solid=(w,h,d,x,y,z)=>colliders.push({x0:x-w/2,x1:x+w/2,z0:z-d/2,z1:z+d/2});
 const add=(key,label,doWhat,description,x,z)=>interactables.push({key:site.id+':'+key,label,
   pos:new V(x,0,z),act:{do:doWhat,text:description}});
 return {THREE:{HemisphereLight:class{},Vector3:V},group,colliders,interactables,sceneObjects,placedProps,
   box,solid,add,cyl:()=>{},torus:()=>{},text:()=>{},shell:()=>{},
   finish:opts=>({...opts,group,colliders,interactables,sceneObjects,placedProps,
     rooms:[{name:title,x0:-7,x1:7,z0:-12,z1:6}],
     spawn:new V(0,0,3.75),exitZone:{x0:-1.05,x1:1.05,z0:5.9,z1:7.2}})};
};
const factory=new Function('createKit',source.replace(/^import .*?;\s*$/gm,'')
 .replace(/^export /gm,'')+'\nreturn buildWasteDepotInterior;')(kit);
const room=factory({id:'landfill',name:'Waste Depot',stock:{rubbish:17}},()=>{},{
 stats:{landfill:8},civic:{homes:{rubbish:3}}});
assert.equal(room.layout.site,'Q8');
assert.equal(room.wasteDepotLayout,true);
assert.equal(room.interactables.length,9);
assert.equal(room.stockAtEntry.rubbish,17);
assert.equal(room.stockAtEntry.kerbside,3);
assert.equal(room.stockAtEntry.reportedDepositsToday,8);
assert.equal(room.staff.pos.z,1.3);
const hit=(x,z,r=.35)=>room.colliders.some(c=>{
 const xx=Math.max(c.x0,Math.min(c.x1,x)),zz=Math.max(c.z0,Math.min(c.z1,z));
 return (x-xx)**2+(z-zz)**2<r*r;
});
assert(!hit(room.spawn.x,room.spawn.z),'Cannot spawn inside a desk');
for(const z of [5,3,1,-1,-3,-5,-7,-9,-10.5])
 assert(!hit(0,z),'Blocked safety corridor at '+z);
for(const p of room.interactables){
 assert(!hit(p.pos.x,p.pos.z),'Buried hotspot '+p.key);
 assert(['waste-depot-status','civic-ledger'].includes(p.act.do),'Unsafe plant action '+p.key);
}
// A flood-fill with player collider radius tests genuine room circulation
// instead of a teleport-only approach to a disconnected hotspot.
const step=.35,minx=-6.6,minz=-11.65,nx=39,nz=50;
const key=(i,j)=>i+','+j,q=[],seen=new Set();
const sx=Math.round((room.spawn.x-minx)/step),sz=Math.round((room.spawn.z-minz)/step);
q.push([sx,sz]);seen.add(key(sx,sz));
for(let n=0;n<q.length;n++){
 const [i,j]=q[n];
 for(const [di,dj] of [[1,0],[-1,0],[0,1],[0,-1]]){
  const a=i+di,b=j+dj,k=key(a,b);
  if(a<0||b<0||a>=nx||b>=nz||seen.has(k)||hit(minx+a*step,minz+b*step))continue;
  seen.add(k);q.push([a,b]);
 }
}
assert(q.length>800);
for(const p of room.interactables)
 assert(q.some(([i,j])=>Math.hypot(minx+i*step-p.pos.x,minz+j*step-p.pos.z)<2.0),
   'Unreachable inspection '+p.key);
console.log('PASS: Q8 unique transfer depot, 9 stations, '+q.length+' accessible cells, intact safe aisle, current rubbish stock and excluded plant controls');
